package main

// Agent-side gRPC client helper (v5.27). The foundation bit: opens a
// StreamMigrationProgress stream to the control plane and pushes
// frames generated by the caller. Kept as a thin wrapper so the
// existing migrate_mtls.go flow can adopt it one frame-source at a
// time without a big-bang rewrite.
//
// Security: the v5.27 server listens in plaintext on :8095 by default
// (management-VLAN-only). A follow-up patch will front it with the
// same TLS cert the HTTPS endpoint uses and validate the agent's
// client cert against the hypervisor cert list. Until then, restrict
// inbound 8095 to trusted sources.

import (
	"context"
	"fmt"
	"time"

	"google.golang.org/grpc"
	"google.golang.org/grpc/credentials/insecure"

	agentpb "kvm-center/gen/agentpb"
)

// ProgressFrame mirrors agentpb.MigrationProgress in a caller-
// friendly form (no proto imports in the migrate_mtls.go critical
// path). The client marshals to the wire type internally.
type ProgressFrame struct {
	MigrationID string
	VMName      string
	SourceHost  string
	DestHost    string
	Phase       string
	ProgressPct int32
	Detail      string
	Error       string
}

// MigrationProgressReporter streams progress frames to the server for
// one migration. Call Send for each frame, Close at the end. The
// stream is unidirectional (client → server); the server's Ack is
// read at Close and returned for logging.
type MigrationProgressReporter struct {
	conn   *grpc.ClientConn
	stream agentpb.AgentService_StreamMigrationProgressClient
	cancel context.CancelFunc
}

// OpenMigrationProgressReporter dials the control plane's gRPC
// endpoint and opens a StreamMigrationProgress stream. `grpcAddr`
// is "host:port" for the server (e.g. "kvm-center:8095"). Context
// controls per-stream lifetime; callers usually bound it to the
// migration's own context so abort + cancellation propagate.
func OpenMigrationProgressReporter(parent context.Context, grpcAddr string) (*MigrationProgressReporter, error) {
	if grpcAddr == "" {
		return nil, fmt.Errorf("grpc-addr empty — migration-progress reporter disabled")
	}
	conn, err := grpc.NewClient(grpcAddr, grpc.WithTransportCredentials(insecure.NewCredentials()))
	if err != nil {
		return nil, fmt.Errorf("grpc dial %s: %w", grpcAddr, err)
	}
	ctx, cancel := context.WithCancel(parent)
	client := agentpb.NewAgentServiceClient(conn)
	stream, err := client.StreamMigrationProgress(ctx)
	if err != nil {
		cancel()
		_ = conn.Close()
		return nil, fmt.Errorf("open stream: %w", err)
	}
	return &MigrationProgressReporter{
		conn:   conn,
		stream: stream,
		cancel: cancel,
	}, nil
}

// Send pushes one frame. Non-fatal errors (transient network blips)
// are returned but shouldn't fail the migration — the caller should
// log + continue; the sync HTTP response + boot reconciler cover the
// durability gap.
func (r *MigrationProgressReporter) Send(f ProgressFrame) error {
	return r.stream.Send(&agentpb.MigrationProgress{
		MigrationId: f.MigrationID,
		VmName:      f.VMName,
		SourceHost:  f.SourceHost,
		DestHost:    f.DestHost,
		Phase:       f.Phase,
		ProgressPct: f.ProgressPct,
		Detail:      f.Detail,
		Error:       f.Error,
		ReportedAt:  time.Now().Unix(),
	})
}

// Close sends EOF, reads the server's Ack, and tears down the
// underlying connection. Safe to call multiple times.
func (r *MigrationProgressReporter) Close() (framesAccepted int32, lastErr string, err error) {
	if r == nil || r.stream == nil {
		return 0, "", nil
	}
	ack, err := r.stream.CloseAndRecv()
	r.cancel()
	_ = r.conn.Close()
	if err != nil {
		return 0, "", err
	}
	return ack.GetFramesAccepted(), ack.GetLastError(), nil
}
